#!/usr/bin/env bash
# allowed_signers current and hooks present (problems). A missing signing key is a warning:
# keys are generated by the ssh preflight, and a fresh machine may not have them yet.
set -euo pipefail
cfg="$HOME/.config/git"
rc=0
for id in "$cfg"/identity.*; do
  [ -f "$id" ] || continue
  key="$(git config --file "$id" user.signingkey || true)"
  key="${key/#\~/$HOME}"
  [ -n "$key" ] || continue
  [ -f "$key" ] || echo "warn: signing key missing for $(basename "$id"): $key (commits there will fail until it exists)"
done
if ! DRY_RUN=1 bash "$DOTFILES_DIR/modules/git/install.sh" 2>/dev/null | grep -q '^skip '; then
  echo "allowed_signers is missing or stale: rerun install"
  rc=1
fi
[ -e "$cfg/template/hooks/commit-msg" ] || {
  echo "missing template/hooks/commit-msg"
  rc=1
}
exit $rc
